// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        uint initialCount = c.depositsCount();
        address target = address(0x123);
        bytes memory emptyData = "";
        vm.deal(address(this), 1 wei);
        vm.prank(address(this));
        c.sendMoney{value: 1 wei}(target, 1 wei, emptyData);
        uint finalCount = c.depositsCount();
        assertTrue(finalCount == initialCount + 1);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address target = address(0x123);
        bytes memory emptyData;

        // First call to sendMoney triggers fallback -> increments depositsCount in reference
        c.sendMoney(target, 0, emptyData);
        // Second call also increments in reference
        c.sendMoney(target, 0, emptyData);

        // Reference: depositsCount == 2; Buggy: depositsCount == 0
        assertTrue(c.depositsCount() == 2);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        (bool sent, ) = address(c).call{value: 0.5 ether}("");
        assertTrue(sent);
        assertEq(c.depositsCount(), 1);
    }
}
